  R('GET', '/api/projects/:id/stats', c => {
    const p = getProject(c.u, c.p[0]); const list = db.issues.filter(i => i.projectId === p.id);
    const byStatus = Object.fromEntries(p.workflow.statuses.map(s => [s.name, 0])), byType = {}, byAssignee = {};
