  if (S.issueKey) { main.append(detailView()); return; }
  if (S.view === 'settings') { main.append(settingsView()); return; }
  if (!S.issues || !S.sprints) { loadIssues().then(render).catch(e => { S.err = e.message; S.issues = []; S.sprints = []; render(); }); return; }
